<script>
  if (vat_free_day == true) {
    

    setCookie('total_quantity', 0, 7);
    //alert(getCookie('total_quantity'));

  }
  $(document).ready(function() {
    
    var product_recc_id = "";
    if(product_recc_id != ""){
      fetch(window.Shopify.routes.root + "recommendations/products.json?product_id=&limit=4")
        .then(response => response.json())
        .then(({ products }) => {
          var currency_cymbol = $("#currecy-symbol").val();
          if (products != null) {
            $(".mini-search-products").html('');
            for(var i = 0; i< products.length; i++){
              if($.inArray('apple_care',products[i].tags) == -1 && $.inArray('apple_care_care+',products[i].tags) == -1 ){
                var text = products[i].title;
                var count = 25;
                var result_title = text.slice(0, count) + (text.length > count ? "..." : "");
                var price = (Math.round(products[i].price) / 100).toFixed(2);
                  $(".mini-search-products").append('<li class="line-frequent-item"><span class="col-set1-frequently"><img class="img-area-frequent"  src='+products[i].featured_image+' alt=""></span><span class="col-set2 frequently-list-product"><a href='+products[i].url+' class="removeline"><span class="mini-frequently-title">'+result_title+'</span></a></span></li>');
              }
            }
          }
        });
    }
    var exphone = [];
    var item_cart = '';
    var view_cart_item = [];
    var view_cart = "";
    var ex_cart = [];
    var dup_id = [];
    $.ajax({
      type: 'GET',
      dataType: 'json',
      url: '/cart.js',
      async: false,
      success: function (cart) {
        if (localStorage.getItem("cart") != undefined || localStorage.getItem("cart") != null) {
          exphone = JSON.parse(localStorage.getItem("cart"));
          if (exphone != null) {
            for (var j = 0; j < exphone.length; j++) {
              if (dup_id.includes(exphone[j]['cart_item_id'])) { } else {
                for (var i = 0; i < cart.items.length; i++) {
                  if (exphone[j]['cart_item_id'] == cart.items[i].key) {
                    item_cart = {}
                    item_cart["cart_item_list_name"] = exphone[j]['cart_item_list_name'];
                    item_cart["cart_item_mpn"] = exphone[j]['cart_item_mpn'];
                    item_cart["cart_item_id"] = exphone[j]['cart_item_id'];
                    if (exphone[j]["cart_search_term"] != "") {
                      item_cart["cart_search_term"] = exphone[j]['cart_search_term'];
                    }
                    ex_cart.push(item_cart);
                    localStorage.setItem("cart_updated", JSON.stringify(ex_cart));
                    dup_id[j] = exphone[j]['cart_item_id'];
                  }
                }
              }
            }
          }
        }
      }
    });
    var search_first = "";
    localStorage.removeItem("cart");
    localStorage.setItem("checkoutpage_store", JSON.stringify(view_cart_item));
    localStorage.setItem("cart", localStorage.getItem("cart_updated"));
    localStorage.removeItem("cart_updated");

    
    $('#close-cart').click(function(evt){
      $("#cart-notification").removeClass("minicart-active");
      $("#cart-notification").hide();
    });

    $(".checkout-custom").click(function(evt){
      if(vat_free_day == true){
        if(getCookie('total_quantity') > vat_free_quantity){
          alert(vat_free_message);
          location.reload();
          return false;
        }
      }
      evt.preventDefault();
      $.ajax({
        type: 'GET',
        url: "/cart?view=minquant",
        async: false,
        success: function(itemData){
          let arr = (itemData.trim().split(',#')).filter(function(v) {
            return v !== '';
          });
          var allow_checkout = 0;
          for (var i = 0; i < arr.length; i++) {
            let arr1 = arr[i].split('<--split-->');
            let prod_id = parseInt(arr1[0]);
            let prduct_quantity = parseInt(arr1[1]);
            let prduct_maxquantity = arr1[2];
            let prduct_key = arr1[3];
            let prduct_title = arr1[4];
            let prduct_variantid = parseInt(arr1[5]);
            let prduct_totalinv = parseInt(arr1[6]);
            let prduct_type = arr1[7];
            if(prduct_maxquantity != ""){
              if(parseInt(prduct_totalinv) < parseInt(prduct_maxquantity)){
                if(parseInt(prduct_quantity) > parseInt(prduct_totalinv)){
                  allow_checkout = 1;
                }
              }else{
                var total_max_product = checkoutMaxquantity(prod_id);
                if(parseInt(total_max_product) > parseInt(prduct_maxquantity)){
                  allow_checkout = 1;
                }
              }
            }else{
              if(parseInt(prduct_quantity) > parseInt(prduct_totalinv)){
                allow_checkout = 1;
              }
            }

          }
          if(allow_checkout == 1){
            alert(quantity_limit_error_message);
            window.location.href= "/cart";
            return false;
          }else{
            window.location.href= `${window.Shopify.routes.root}checkout`;
          }
        }
      });
  });
  function checkoutMaxquantity(product_id){
    var total_max_quantity = 0;
    var product_id = product_id;
    $.ajax({
      type: 'GET',
      dataType: 'json',
      async: false,
      url: '/cart.js',
      success: function(cart){
        for(var i = 0; i< cart.items.length; i++){
          var product_cartid = cart.items[i].product_id;
          if(product_cartid == product_id){
            total_max_quantity += cart.items[i].quantity;
          }
        }
      }
    });
    return total_max_quantity;
  }
  var checkExist = setInterval(function() {
    if ($('.mini-frequently-title').length) {
      clearInterval(checkExist);
      $(".mini-frequently-title").on("click",function(){
        localStorage.setItem("productList","minicart_FBT");
      })
      }
    }, 100);
  });
</script>

