/* Tombol */
.btn-SLOT {
  position: relative;
  background: linear-gradient(0deg,rgb(18, 18, 18) 0%, rgb(219 26 26) 100%);
  background-size: 300%;
  animation: gradientFlow 6s infinite linear;
  border: none;
  padding: 12px 0;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 700;
  color: #ffffff;
  width: 100%;
  cursor: pointer;
  overflow: hidden;
  box-shadow: 0 4px 0 #000000;
  transition: all 0.3s ease;
}

@keyframes gradientFlow {
  0% { background-position: 0% 50%; }
  100% { background-position: 100% 50%; }
}

.btn-SLOT::before {
  content: "";
  position: absolute;
  top: 0;
  left: -75%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    120deg,
    rgb(204, 170, 235) 0%,
    rgba(0,0,0,0.4) 50%,
    rgb(222, 190, 248) 100%
  );
  animation: shine 3s infinite linear;
}

@keyframes shine {
  0% { left: -75%; }
  100% { left: 125%; }
}

.btn-SLOT:hover {
  background: linear-gradient(90deg,rgba(49, 0, 117, 1) 0%, rgba(163, 26, 219, 1) 100%);
  color: #ffffff;
  box-shadow: 0 4px 0 #e60b0b;
}
</style>

