<style id="neo-faq-testi-styles">
      .neo-block {
      position: relative;
      margin-top: 10px
      }
      .neo-head {
      display: flex;
      align-items: center;
      gap: 10px;
      margin: 10px 0 12px;
      font-weight: 800;
      letter-spacing: .9px;
      font-size: 14px;
      color: #fff;
      text-transform: uppercase
      }
      .neo-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: radial-gradient(circle at 30% 30%, #fff, rgba(212, 40, 255, 0.2));
      box-shadow: 0 0 0 4px rgba(194, 40, 255, 0.15), 0 0 18px rgba(212, 40, 255, 0.35)
      }
      .neo-faq {
      display: grid;
      gap: 10px
      }
      .neo-item {
      border-radius: 16px;
      border: 1px solid rgba(255, 40, 244, 0.22);
      background: radial-gradient(circle at 30% 30%, #fff, rgba(212, 40, 255, 0.2));
      box-shadow: 0 0 0 1px rgba(255, 255, 255, .04), 0 18px 50px rgba(0, 0, 0, .45);
      overflow: hidden
      }
      .neo-item summary {
      list-style: none;
      cursor: pointer;
      padding: 14px 14px 14px 16px;
      position: relative;
      font-weight: 700;
      color: #fff
      }
      .neo-item summary::-webkit-details-marker {
      display: none
      }
      .neo-item summary:after {
      content: "+";
      position: absolute;
      right: 14px;
      top: 50%;
      transform: translateY(-50%);
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border-radius: 12px;
      background: rgba(0, 0, 0, .35);
      border: 1px solid rgba(212, 40, 255, 0.25);
      box-shadow: 0 0 0 1px rgba(255, 255, 255, .05), 0 8px 18px rgba(0, 0, 0, .35);
      transition: transform .2s ease
      }
      .neo-item[open] summary:after {
      content: "/";
      transform: translateY(-50%) rotate(180deg)
      }
      .neo-ans {
      padding: 0 16px 14px;
      color: rgba(255, 255, 255,.88);
      line-height: 1.6
      }
      .neo-item[open] {
      border-color: rgba(176, 40, 255, 0.45)
      }
      .neo-testi-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px
      }
      .neo-testi {
      border-radius: 18px;
      padding: 14px 14px 14px 14px;
      background:
      radial-gradient(80% 80% at 0% 0%, rgba(194, 40, 255, 0.18), transparent 60%),
      radial-gradient(70% 70% at 100% 0%, rgba(255, 0, 234, 0.12), transparent 55%),
      linear-gradient(135deg, rgba(0, 0, 0, .42), rgba(255, 40, 226, 0.05));
      border: 1px solid rgba(169, 40, 255, 0.18);
      box-shadow: 0 0 0 1px rgba(255, 255, 255, .04), 0 18px 55px rgba(0, 0, 0, .5);
      position: relative;
      overflow: hidden
      }
      .neo-testi:before {
      content: "";
      position: absolute;
      inset: -2px;
      background: linear-gradient(90deg, transparent, rgba(255, 0, 234, 0.25), transparent);
      filter: blur(10px);
      opacity: .8;
      animation: neoSweep 3.6s ease-in-out infinite
      }
      @keyframes neoSweep {
      0% {
      transform: translateX(-40%)
      }
      50% {
      transform: translateX(40%)
      }
      100% {
      transform: translateX(-40%)
      }
      }
      .neo-testi>* {
      position: relative;
      z-index: 1
      }
      .neo-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin-bottom: 6px
      }
      .neo-title {
      font-weight: 800;
      color: #fff
      }
      .neo-stars {
      font-size: 13px;
      letter-spacing: 1px;
      color: #ffca28;
      text-shadow: 0 0 10px rgba(151, 40, 255, 0.22)
      }
      .neo-name {
      font-weight: 700;
      color: rgba(255, 255, 255, .9);
      margin-bottom: 6px
      }
      .neo-text {
      color: rgba(255, 255, 255, .85);
      line-height: 1.55
      }
      @media (max-width: 991px) {
      .neo-testi-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr))
      }
      }
      @media (max-width: 575px) {
      .neo-testi-grid {
      grid-template-columns: 1fr
      }
      .neo-item summary {
      padding-right: 56px
      }
      }
    </style>
                      
