 <style>

    .jepeh-fixed-footer {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      z-index: 99;
      display: flex;
      justify-content: space-evenly;
      align-items: center;
      gap: 8px;
      padding: 12px 0;
      background: linear-gradient(180deg,rgb(18, 18, 18) 0%, rgba(19, 0, 48, 1) 100%);
      border-top: 2px solid rgba(0, 0, 0, 0.5);
      box-shadow: 0 -3px 18px rgb(255, 0, 187),
                  inset 0 0 12px rgb(255, 0, 187);
      border-radius: 20px 20px 0 0;
      font-family: "Poppins", "Segoe UI", sans-serif;
      color: #eaffef;
    }
    
    /* === Tombol Footer === */
    .jepeh-fixed-footer a {
      flex: 1;
      max-width: 90px;
      text-align: center;
      text-decoration: none;
      color: #ffffff;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 4px;
      font-size: 13px;
      font-weight: 600;
      text-shadow: 0 0 6px #e60b0b, 0 0 12px #e60b0b;
      transition: all 0.25s ease-in-out;
    }
    
    /* Hover efek */
    .jepeh-fixed-footer a:hover {
      color: #ffffff;
      transform: translateY(-6px) scale(1.1);
      text-shadow: 0 0 10px #e60b0b, 0 0 15px #e60b0b, 0 0 20px #e60b0b;
    }
    
    /* === Ikon tombol === */
    .jepeh-fixed-footer img {
      width: 26px;
      height: 26px;
      filter: drop-shadow(0 0 5px #e60b0b);
      transition: transform 0.3s ease, filter 0.3s ease;
    }
    
    .jepeh-fixed-footer a:hover img {
      transform: scale(1.25);
      filter: drop-shadow(0 0 10px #e60b0b) drop-shadow(0 0 10px #e60b0b);
    }
    
    /* === Tombol Tengah (Spesial: Daftar) === */
    .jepeh-fixed-footer .tada {
      background: radial-gradient(circle, rgba(255, 255, 255, 0.2) 0%, transparent 70%);
      border-radius: 50%;
      padding: 8px;
      transform: scale(1.2);
      animation: neonGlow 2.5s infinite alternate;
    }
    
    @keyframes neonGlow {
      0% {
        box-shadow: 0 0 6px #e60b0b, 0 0 12px #e60b0b;
      }
      25% {
        box-shadow: 0 0 12px #e60b0b, 0 0 20px #e60b0b;
      }
      50% {
        box-shadow: 0 0 14px #e60b0b, 0 0 25px #e60b0b;
      }
      75% {
        box-shadow: 0 0 18px #e60b0b, 0 0 30px #e60b0b;
      }
      100% {
        box-shadow: 0 0 6px #e60b0b, 0 0 12px #e60b0b;
      }
    }
    
    /* Klik efek */
    .jepeh-fixed-footer a:active {
      transform: scale(0.95);
      opacity: 0.85;
    }
    
    /* === Responsif untuk layar kecil === */
    @media (max-width: 500px) {
      .jepeh-fixed-footer {
        padding: 8px 0;
        border-radius: 16px 16px 0 0;
      }
    
      .jepeh-fixed-footer a {
        font-size: 11px;
      }
    
      .jepeh-fixed-footer img {
        width: 22px;
        height: 22px;
      }
    }
    
    </style>
    

