// APPLE CARE UPDATE (TYPE ADDED)  

// ===== Helper: map container id -> apple_care+_type =====
function getAppleCareType(containerId) {
  switch (containerId) {
    case 'apple-care-add':   return 'AppleCare+';
    case 'theftloss-add':    return 'AppleCare+ with Theft and Loss';
    case 'secWarranty-add':  return 'Partner Protection Plan';
    case 'insurance-remove': return 'No coverage';
    default: return null;
  }
}

// ===== State: remembers which cart button opened the T&L acceptance modal =====
// Used by .js-tl-modal-add handler to pull cart-specific data (currency, brand, price)
// when confirmation comes from a cart context.
window.__lastCartTlOpener = null;

// ===== pdp AppleCare+ (regular) =====
$(document).on('click', 'label[for="add-apple-care"]', function(event) {
  if (event.target.tagName.toLowerCase() === 'input') return;

  const label = this;
  const input = document.getElementById(label.getAttribute('for'));
  if (!input) return;

  setTimeout(async function() {
    if (!input.checked) return;

    const parent = label.closest('.add-on-product-style');
    const container = label.closest('.container-box-2');
    if (!container || container.id !== 'apple-care-add') return;

    const appleCarePlan = elementText(parent ? parent.querySelector('h3') : null);
    const appleCareType = getAppleCareType(container.id);
    const productData = await adobeProductData();

    window.APLdigitalData = window.APLdigitalData || [];
    window.APLdigitalData.push({
      'event': 'applecare+_add',
      'apple_care+_type': appleCareType,
      'apple_care+_plan': appleCarePlan,
      'product': productData?.product_name,
    });

    console.log('Applecare+ selection tracked', {
      apple_care_type: appleCareType,
      apple_care_plan: appleCarePlan
    });
  }, 0);
});

// ===== AppleCare+ with Theft and Loss (modal confirm — PDP + cart contexts) =====
// Triggered when user confirms T&L purchase via the acceptance modal CTA.
// Modal ID prefix tells us the context:
//   - modal-pdp-...        -> PDP (use PDP card h3, fall back to product name)
//   - modal-cto-cart-...   -> Cart (use stored cart opener, pull cart item data)
$(document).on('click', '.js-tl-modal-add', async function() {
  const modalBtn = this;
  const modalId = modalBtn.dataset.tlModalId || '';
  const appleCareType = getAppleCareType('theftloss-add');

  // --- Cart context ---
  if (modalId.startsWith('modal-cto-cart-')) {
    const opener = window.__lastCartTlOpener;
    if (!opener) {
      console.warn('T&L modal confirmed in cart context but no opener stored');
      return;
    }

    const parent = opener.closest('.cart_itemadd');
    const title = parent ? parent.querySelector('.apple-care-card-title') : null;
    const appleCarePlan = elementText(title);

    const mainProductIndex = opener.dataset.forproduct;
    const mainProductParent = document.getElementById(`CartItem-${mainProductIndex}`);
    const productData = JSON.parse(
      mainProductParent.querySelector('.adobe-analytics-cart-item-data').textContent
    ).payload;

    window.APLdigitalData = window.APLdigitalData || [];
    window.APLdigitalData.push({
      'event': 'applecare+_add',
      'apple_care+_type': appleCareType,
      'apple_care+_plan': appleCarePlan,
      'product': productData?.product_name,
      'currency': productData?.currency,
      'product_price': productData?.product_price,
      'brand': productData?.brand,
    });

    console.log('Applecare+ selection tracked (cart modal confirm)', {
      apple_care_type: appleCareType,
      apple_care_plan: appleCarePlan,
      modal_id: modalId,
    });

    window.__lastCartTlOpener = null; // reset
    return;
  }

  // --- PDP context (default) ---
  const pdpContainer = document.getElementById('theftloss-add');
  const pdpParent = pdpContainer ? pdpContainer.closest('.add-on-product-style') : null;
  const h3Plan = elementText(pdpParent ? pdpParent.querySelector('h3') : null);

  const productData = await adobeProductData();
  const appleCarePlan = h3Plan && h3Plan.trim() ? h3Plan : 'AppleCare+ with Theft and Loss for ' + productData?.product_name;

  window.APLdigitalData = window.APLdigitalData || [];
  window.APLdigitalData.push({
    'event': 'applecare+_add',
    'apple_care+_type': appleCareType,
    'apple_care+_plan': appleCarePlan,
    'product': productData?.product_name,
  });

  console.log('Applecare+ selection tracked (pdp modal confirm)', {
    apple_care_type: appleCareType,
    apple_care_plan: appleCarePlan,
    modal_id: modalId,
  });
});

