// VIDEO EVENTS 
/**
 * Returns the slide URL for a given video element.
 * Traverses up the DOM to find the closest .slideshow__slide,
 * then extracts the href from the .full-link anchor inside it.
 *
 * @param {HTMLVideoElement} videoElement
 * @returns {string|undefined} Absolute URL or undefined if not found
 */
function videoslideUrl(videoElement) {
  const slide = videoElement.closest('.slideshow__slide');
  if (!slide) return undefined;

  const link = slide.querySelector('a.full-link');
  if (!link) return undefined;

  const href = link.getAttribute('href');
  if (!href) return undefined;

  // Convert relative path to absolute URL using current origin
  return new URL(href, window.location.origin).href;
}

/**
 * Returns the name/identifier of a given video element.
 * Used as a unique video_id in all tracking events.
 *
 * @param {HTMLVideoElement} target
 * @returns {string}
 */
function videoSliderName(target) {
  // Grab the src of the first <source> tag, or fall back to the video's own src
  const source = target.querySelector('source');
  return source ? source.src : target.src;
}

// ─────────────────────────────────────────────
// VIDEO PLAY
// Fires once per video when playback starts.
// Skips if the same video_play event was already pushed.
// ─────────────────────────────────────────────
$('video').on('play', function () {
  const target  = this;
  const vidName = videoSliderName(target);
  const fullURL     = videoslideUrl(target);
  const url = stripDomain(fullURL);

  window.APLdigitalDataClient = window.APLdigitalDataClient || [];

  // Deduplicate: fire only once per video
  if (window.APLdigitalDataClient.find(
    data => data.event === 'video_play' && data.video_id === vidName
  )) return;

  // Build payload; slide_url is included only if the video lives inside a slide
  const payload = {
    event:    'video_play',
    video_id: vidName,
    ...(url && { click_url: url })
  };

  window.APLdigitalDataClient.push(payload);

  window.APLdigitalData = window.APLdigitalData || [];
  window.APLdigitalData.push(payload);
});

// ─────────────────────────────────────────────
// VIDEO PAUSE
// Fires once per video when playback is paused.
// Ignores the final "pause" that fires right before the ended event.
// ─────────────────────────────────────────────
$('video').on('pause', function () {
  const target  = this;
  const vidName = videoSliderName(target);
  const fullURL     = videoslideUrl(target);
  const url = stripDomain(fullURL);

  // Do not track pause if the video has already ended (ended triggers pause too)
  if (target.ended) return;

  window.APLdigitalDataClient = window.APLdigitalDataClient || [];

  // Deduplicate: fire only once per video
  if (window.APLdigitalDataClient.find(
    data => data.event === 'video_pause' && data.video_id === vidName
  )) return;

  const payload = {
    event:    'video_pause',
    video_id: vidName,
    ...(url && { click_url: url })
  };

  window.APLdigitalDataClient.push(payload);

  window.APLdigitalData = window.APLdigitalData || [];
  window.APLdigitalData.push(payload);
});

// ─────────────────────────────────────────────
// VIDEO PROGRESS + COMPLETE
// Fires on every timeupdate tick.
// Tracks progress milestones: 25%, 50%, 75%.
// Tracks completion separately as video_complete at 100%.
// Each milestone fires only once per video.
// ─────────────────────────────────────────────
$('video').on('timeupdate', function () {
  const target    = this;
  const vidName   = videoSliderName(target);
  const fullURL       = videoslideUrl(target);
  const url = stripDomain(fullURL);
  const duration  = target.duration;
  const currentTime = target.currentTime;

  // Avoid division by zero or NaN before metadata is loaded
  if (!duration || isNaN(duration)) return;

  const progress = Math.round((currentTime / duration) * 100);

  // Milestones to track (descending order so we match the highest reached threshold)
  const steps = [100,75, 50, 25, 0];
  const progressThreshold = steps.find(step => progress >= step);

  window.APLdigitalDataClient = window.APLdigitalDataClient || [];

  // ── 100% → video_complete ──────────────────
  if (progressThreshold === 100) {

    // Deduplicate: fire only once per video
    if (window.APLdigitalDataClient.find(
      data => data.event === 'video_complete' && data.video_id === vidName
    )) return;

    const payload = {
      event:    'video_complete',
      video_id: vidName,
      ...(url && { click_url: url })
    };

    window.APLdigitalDataClient.push(payload);

    window.APLdigitalData = window.APLdigitalData || [];
    window.APLdigitalData.push(payload);

  // ── 25% / 50% / 75% → video_progress ──────
  } else if (progressThreshold > 0) {

    // Deduplicate: fire only once per milestone per video
    if (window.APLdigitalDataClient.find(
      data =>
        data.event          === 'video_progress' &&
        data.video_id       === vidName          &&
        data.video_progress === `${progressThreshold}%`
    )) return;

    const payload = {
      event:          'video_progress',
      video_id:       vidName,
      video_progress: `${progressThreshold}%`,
      ...(url && { click_url: url })
    };

    window.APLdigitalDataClient.push(payload);

    window.APLdigitalData = window.APLdigitalData || [];
    window.APLdigitalData.push(payload);
  }

  // 0% threshold is intentionally ignored — no event fired at 0%
});

